use crate::span;
use std::collections::HashMap;

const RAW: &str = include_str!("../loomkit/emit.lst");

#[derive(Clone)]
pub struct Slot {
    pub label: String,
    pub reply: String,
}

fn parse_line(line: &str) -> Option<(i64, Slot)> {
    let mut parts = line.split('\t');
    let label = parts.next()?.trim().to_string();
    let wire: i64 = parts.next()?.trim().parse().ok()?;
    let reply = parts.next()?.trim().to_string();
    if label.is_empty() || reply.is_empty() {
        return None;
    }
    Some((wire, Slot { label, reply }))
}

pub fn rib_b() -> HashMap<i64, Slot> {
    let mut slots = HashMap::new();
    for line in RAW.lines().filter(|line| !line.trim().is_empty()).take(span::rib_a()) {
        if let Some((wire, slot)) = parse_line(line) {
            slots.insert(wire, slot);
        }
    }
    slots
}

pub fn tap(n: i64) -> i32 {
    let slots = rib_b();
    let reply = slots.get(&n).map(|slot| slot.reply.as_str()).unwrap_or("fallthrough");
    println!("{{\"wire\":{},\"reply\":\"{}\"}}", n, reply);
    0
}
EOF
cat > /app/lidpit/plug.rs <<'EOF'
use crate::cards;
use crate::loom;
use crate::table;
use crate::tally;
use std::fs;

pub fn rib_c() -> i32 {
    let _ = loom::emit();
    let spec = cards::load();
    let hopper = table::rib_b();
    let compiled_count = tally::lines();

    let complete = compiled_count == spec.len()
        && hopper.len() == spec.len()
        && spec.iter().all(|row| {
            hopper.get(&row.wire).map(|slot| {
                slot.label == row.label && slot.reply == row.reply
            }).unwrap_or(false)
        });

    let _ = fs::create_dir_all("/app/corkbay");
    if !complete {
        let served = spec.iter().filter(|row| {
            hopper.get(&row.wire).map(|slot| {
                slot.label == row.label && slot.reply == row.reply
            }).unwrap_or(false)
        }).map(|row| format!("\"{}\"", row.label)).collect::<Vec<_>>().join(",");
        let text = format!("{{\"served\":[{}],\"status\":\"open\"}}\n", served);
        let _ = fs::write("/app/corkbay/seal.json", text);
        return 1;
    }

    let served = spec.iter()
        .map(|row| format!("\"{}\"", row.label))
        .collect::<Vec<_>>()
        .join(",");
    let text = format!("{{\"served\":[{}],\"status\":\"sealed\"}}\n", served);
    let _ = fs::write("/app/corkbay/seal.json", text);
    0
}
EOF
